import{_ as t,c as p,o as s,af as a}from"./chunks/framework.zX5h-Rkw.js";const l=JSON.parse('{"title":"5.5 后记","description":"","frontmatter":{"title":"5.5 后记"},"headers":[],"relativePath":"archives_n_arts/arts/nambu_red/5.5.md","filePath":"archives_n_arts/arts/nambu_red/5.5.md"}'),n={name:"archives_n_arts/arts/nambu_red/5.5.md"};function o(e,r,_,g,i,c){return s(),p("div",null,[...r[0]||(r[0]=[a('<h1 id="五" tabindex="-1">五 <a class="header-anchor" href="#五" aria-label="Permalink to “五”">​</a></h1><h2 id="_5-后记" tabindex="-1">5. 后记 <a class="header-anchor" href="#_5-后记" aria-label="Permalink to “5. 后记”">​</a></h2><p>这本《南武红》，是一部记录革命斗争、人民解放的纪实报告。</p><p>它记载了联合主义思想体系的形成过程，记载了我们从1984年开始筹备革命，到1996年公开成立南武联合党，到1999年领导南武进步革命并建立联合主义南武共和国，直至今天继续进行社会主义革命和建设的全过程。这是三十年革命斗争的思想总结，也是我们继续前进的理论武器。</p><p>书名为《南武红》。红，是革命的颜色，是无产阶级的旗帜，是人民联合的象征。联合主义的本质，就是用真理武装人民，用斗争锻造新人，用革命改造世界。</p><p>谨以此书，献给为南武解放事业、为建立和建设联合主义南武共和国无畏献身的每一位联合党人！</p><p>全书从“联合主义的源流”“人民联合的实现”“社会主义建设之路”“展望未来”四个方面，系统阐述革命理论，总结斗争经验，指导继续革命。</p><p><strong>革命的根本问题是政权问题，而夺取政权和巩固政权的根本，在于理论的武装和思想的统一。</strong></p><p>没有革命的理论，就没有革命的运动。掌握革命理论，是领导人民的首要条件；建立完整的思想体系，是革命成功的根本保证。理论必须同实践相结合，理论必须为群众所掌握，理论一旦掌握群众，就会变成改造世界的物质力量。</p><p>我们南武联合党是一个有着十多年地下斗争历史的革命政党。这个党的理论基础在哪里？在旧社会的黑暗中对真理的探索里，在“融工运动”的革命实践里，在“坚忍、奉公、斗争、联合”的革命精神里，在九九建制开创的历史新纪元里，在联合主义凝练的科学理论里。</p><p><strong>理论联系实际，是我们的一贯方针。</strong></p><p>我们很早就认识到：革命不能迁就少数的动摇分子和机会主义者，革命必须依靠大多数的坚定革命者，依靠最广大的人民群众。这就是我们的群众路线，这就是我们的革命方法。</p><p>我们用“思想武装”团结人民。厚植“南武人，爱南武，为南武”的革命情怀，用南武精神铸就无产阶级先锋队，让革命真理照亮每个劳动者的心灵。我们开展“人民联合、阶级斗争、批私斗修、永续革命”的革命教育，确立联合主义指导思想，创建“全面领导制”“联合所有制”等革命制度，搭建“自我革命、自我教育”的人民民主平台。我们让每个南武人铭记：<strong>没有斗争就没有进步，没有觉悟就没有解放，革命胜利在斗争中，人民当家在联合中。</strong></p><p><strong>革命是理论创新的源泉，斗争是理论发展的土壤。</strong></p><p>革命就是一个寻找真理的场所，一个觉醒人民的场所。历史和未来在这里交汇，国内外革命经验在这里融通。理论联系实际，对革命事业的发展、对人民的解放，太重要了！领导革命，就是在理论与实践的结合中前进：阶级斗争的结合、思想改造的结合、组织建设的结合、政权建设的结合，归根到底是革命理论与革命实践的结合。</p><p>我们坚持了十五年的地下革命探索，从秘密斗争到公开建党，从武装起义到夺取政权，一步步实现了“团结全南武人民，解放全南武劳动者，建立人民当家作主的社会主义国家”的革命理想。1996年公开成立南武联合党，是理论与实践相结合的伟大尝试。我们对党员的要求是：“你不一定参加过武装斗争，但你必须具备革命觉悟。”我们把理论学习与革命实践深度融合，把联合主义思想与具体斗争紧密结合，因为革命更注重过程，更注重实践，更注重培养人民的阶级意识和革命思维。</p><p>建立联合主义南武共和国后，我们始终把“人民联合，思想统一，革命到底”作为基本方针。<strong>夺取政权不容易，巩固政权更不容易。</strong></p><p>九九建制后的十五年，是继续革命的十五年，是改造旧世界、建设新世界的十五年。我们进行了三大革命运动：<strong>思想改造运动</strong>，肃清旧意识形态，树立联合主义世界观；<strong>经济改造运动</strong>，消灭剥削制度，建立联合所有制；<strong>社会改造运动</strong>，打碎旧国家机器，建立全面领导制。这是一场深刻的社会主义革命，是一场触及人们灵魂的大革命。</p><p>我们同修正主义进行了坚决斗争，同资产阶级思想进行了坚决斗争，同官僚主义、机会主义进行了坚决斗争。<strong>阶级斗争没有熄灭，革命没有完成。</strong>只要还有阶级存在，阶级斗争就要继续；只要还有资本主义复辟的危险，革命就要继续。我们要批私斗修，要把社会主义革命进行到底！</p><p><strong>在长期的革命斗争中，我们深刻认识到一条真理：集体的力量是无穷的，人民的力量是无穷的。</strong></p><p>革命者个人的力量虽然有限，但人民群众联合起来的力量是无限的。我们不能因个人力量之小而消极，也不能因目标之大而迷茫。南武的革命辩证法，就是从“小”处着手——从每个无产者的觉醒开始，从每个同志的进步开始，积小成大，聚沙成塔，成就解放全南武的伟大事业。</p><p><strong>革命的辩证法是什么？是矛盾论，是主次之分，是重点突破。</strong></p><p>我们坚持一切从实际出发，坚持具体问题具体分析，坚持抓住主要矛盾和矛盾的主要方面。搞革命要坚持原则，明确方向，团结大多数，孤立少数敌人。要稳扎稳打，逐步推进，积累力量，等待时机，推翻旧世界，建立新制度。个人服从集体，局部服从整体，现在服从长远。<strong>坚持真理，改正错误，这是我们的原则；依靠人民，相信群众，这是我们的力量。</strong></p><p>革命理论这个东西，很多人说不清楚，但革命实践证明它是正确的！理论的正确性要在实践中检验，理论的生命力要在斗争中展现。我们的理论是活的理论，是发展的理论，是同南武革命实践紧密结合的理论。</p><p>感谢人民！感谢几十年来和我并肩战斗的联合党人！是人民群众创造了历史，是联合党人成就了伟业。我们的力量来自人民，我们的胜利属于人民！</p><p><strong>南武人，爱南武，为南武！</strong></p><p>南武香淳</p><p>2014年5月14日</p>',28)])])}const h=t(n,[["render",o]]);export{l as __pageData,h as default};
